function updateStageOverview(){const totalNode=$('taskCount');if(!totalNode)return;const card=totalNode.closest('.asideCard');if(!card)return;card.classList.add('overviewCard');let region=$('stageOverview');const expanded=new Set(region?Array.from(region.querySelectorAll('details[open]')).map(d=>+d.dataset.stageDetails):[]);if(!region){region=document.createElement('div');region.id='stageOverview';region.className='stageOverview';card.append(region)}region.innerHTML=`<div class="stageOverviewHeading"><b>פירוט לפי שלב</b><span>הושלמו / סך המשימות</span></div><div class="stageOverviewList">${stages.map((stage,index)=>{const total=stage.tasks.length,done=stage.tasks.filter((_,task)=>data.checks[index]?.[task]).length,percent=Math.round(done/total*100),status=done===total?'הושלם':done?'בתהליך':'ממתין להתחלה';return `<section class="stageOverviewItem" style="--stage-color:${stage.color}"><button class="stageOverviewLink ${index===data.stage&&view==='journey'?'current':''}" data-stage="${index}" aria-label="מעבר לשלב ${index+1}: ${esc(stage.name)}, ${done} מתוך ${total} משימות הושלמו"><span class="stageOverviewNumber">${index+1}</span><span class="stageOverviewTitle">${esc(stage.name)}</span><span class="stageOverviewFraction">${done}<small>/${total}</small></span></button><div class="stageOverviewProgress" role="progressbar" aria-label="התקדמות שלב ${index+1}" aria-valuemin="0" aria-valuemax="${total}" aria-valuenow="${done}"><i style="width:${percent}%"></i></div><div class="stageOverviewMeta"><span>${status}</span><span>${percent}%</span></div><details data-stage-details="${index}" ${expanded.has(index)?'open':''}><summary>פירוט המשימות</summary><ul>${stage.tasks.map((task,i)=>`<li class="${data.checks[index]?.[i]?'taskDone':''}"><span aria-hidden="true">${data.checks[index]?.[i]?'✓':'○'}</span><span>${esc(task)}<small>${data.checks[index]?.[i]?'הושלם':'טרם הושלם'}</small></span></li>`).join('')}</ul></details></section>`}).join('')}</div>`}
const updateBeforeStageOverview=update;update=function(){updateBeforeStageOverview();updateStageOverview()};updateStageOverview();
